        "type": "5' UTR SNP",
        "ref": "G",
        "alt": "A",
        "gene": "membrin (LOC412913)",
        "trait": "Behavioral Caste Differentiation",
        "description": "A transition in the 5'-UTR of membrin. Scout bees are predominantly homozygous for the reference (G) allele, while recruit bees have a higher frequency of the alternate (A) allele.",
