    "description": "본 웹 어플리케이션은 최신 동양종 꿀벌 참조 유전체 어셈블리인 <strong>AcerK1.0</strong>(RefSeq: GCF_029169275.1)을 기준으로 기존 문헌 연구에서 발굴된 행동 형질(sucrose 민감성, 채집 분업 등), 기후 및 환경 적응(한랭 적응, 고지대 적응 등), 질병 저항성(낭충봉아부패병 저항성) 관련 QTL과 핵심 유전자(Atpalpha, RAPTOR, HO-1, Vg 등), 그리고 저항성 특이적 SNP 변이들의 물리적 위치를 재매핑하여 종합적인 시각적 통찰을 제공합니다.",
